package io.github.jackotom.hongguo.android;

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

/** Actual controller with synthetic SOAP replies; no sockets, device or media. */
public final class DlnaControlDiagnosticsTest {
    private static final String SERVICE="urn:schemas-upnp-org:service:AVTransport:1", SOAP="http://schemas.xmlsoap.org/soap/envelope/";
    private static final String SECRET="NEVER_EXPOSE_THIS_TOKEN", MEDIA="http://192.168.1.2:8080/media/"+SECRET+"/video.mp4";
    private static int checks,passed,failed;
    private interface Checked {void run() throws Exception;}
    private static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static void group(String name,Checked test){try{test.run();passed++;System.out.println("PASS ControlDiagnostics "+name);}catch(Throwable failure){failed++;System.out.println("FAIL ControlDiagnostics "+name+": "+failure.getMessage());}}
    private static DlnaDevice device()throws IOException{return new DlnaDevice("uuid:fixture","Fixture","192.168.1.20",URI.create("http://192.168.1.20:1400/control"),SERVICE);}
    private static String action(Map<String,String> headers){String value=headers.get("SOAPAction");return value.substring(value.indexOf('#')+1,value.length()-1);}
    private static String soap(String action,String contents){return "<s:Envelope xmlns:s=\""+SOAP+"\"><s:Body><u:"+action+"Response xmlns:u=\""+SERVICE+"\">"+contents+"</u:"+action+"Response></s:Body></s:Envelope>";}
    private static DlnaNetwork.Response response(int status,String body){return new DlnaNetwork.Response(status,Collections.emptyMap(),body.getBytes(StandardCharsets.UTF_8));}
    private static String fault(String code,String description){return "<s:Envelope xmlns:s=\""+SOAP+"\"><s:Body><s:Fault><faultcode>s:Client</faultcode><faultstring>UPnPError</faultstring><detail><UPnPError xmlns=\"urn:schemas-upnp-org:control-1-0\"><errorCode>"+code+"</errorCode><errorDescription>"+description+"</errorDescription></UPnPError></detail></s:Fault></s:Body></s:Envelope>";}
    private static String diagnostics(DlnaControl control)throws Exception{return (String)DlnaControl.class.getMethod("diagnostics").invoke(control);}
    private static IOException rejected(Checked request)throws Exception{try{request.run();}catch(IOException failure){return failure;}throw new AssertionError("expected original failure semantics");}
    private static void typed(IOException failure,String action,int http,String upnp)throws Exception{
        check(failure.getClass().getSimpleName().equals("ActionException"),"typed action failure");
        check(action.equals(failure.getClass().getField("action").get(failure)),"action tag");
        check(((Number)failure.getClass().getField("httpStatus").get(failure)).intValue()==http,"HTTP status tag");
        check(upnp.equals(failure.getClass().getField("upnpCode").get(failure)),"UPnP code tag");
        check(failure.getMessage().contains(action),"readable exception contains exact action");
        check(failure.getCause()!=null,"cause retained");
    }
    private static void privateBounded(String text){check(text.length()<=768,"bounded summary");for(String forbidden:Arrays.asList(SECRET,MEDIA,"<s:Envelope","CurrentURI","fixture title"))check(!text.contains(forbidden),"summary omits private URI/token/SOAP/title: "+forbidden);check(!java.util.regex.Pattern.compile("(?<![0-9.])192\\.168\\.1\\.2(?![0-9.])").matcher(text).find(),"summary omits exact media host without rejecting receiver192.168.1.20");}
    private static DlnaControl normal(List<String> calls)throws IOException{return new DlnaControl(device(),(u,m,h,b,t)->{
        String action=action(h);calls.add(action);check(m.equals("POST")&&t==4000,"transport method and deadline unchanged");
        String fields=action.equals("GetTransportInfo")?"<CurrentTransportState>PLAYING</CurrentTransportState>":action.equals("GetPositionInfo")?"<TrackURI>"+MEDIA+"</TrackURI><RelTime>00:00:00</RelTime><TrackDuration>NOT_IMPLEMENTED</TrackDuration>":"";
        return response(200,soap(action,fields));
    });}
    public static void main(String[] args)throws Exception{
        group("initial summary never claims receipt or playback",()->{String text=diagnostics(normal(new ArrayList<>()));check(text.contains("SetAVTransportURI")&&text.contains("Play")&&text.contains("尚未请求"),"initial action states");check(text.contains("不代表")&&text.contains("播放"),"receipt is explicitly not playback proof");privateBounded(text);});
        group("SetURI and Play report command receipt without changing actual SOAP sequence",()->{List<String> calls=new ArrayList<>();DlnaControl c=normal(calls);c.setMedia(MEDIA,"fixture title");c.play();DlnaControl.Status s=c.status();check(s.state.equals("PLAYING")&&s.mediaUri.equals(MEDIA)&&s.positionMs==0&&s.durationMs==0,"status values unchanged");check(calls.equals(Arrays.asList("SetAVTransportURI","Play","GetTransportInfo","GetPositionInfo")),"no added actions, retries or fallbacks");String text=diagnostics(c);check(text.contains("SetAVTransportURI=已受理")&&text.contains("Play=已受理"),"separate receipt states");privateBounded(text);});
        group("new SetURI resets previous Play receipt",()->{DlnaControl c=normal(new ArrayList<>());c.setMedia(MEDIA,"fixture title");c.play();c.setMedia(MEDIA+"?next=1","fixture title");check(diagnostics(c).contains("Play=尚未请求"),"old Play receipt is not reused for a new media handoff");});
        for(String selected:Arrays.asList("SetAVTransportURI","Play","Pause","Stop","Seek","GetTransportInfo","GetPositionInfo"))group("network failure names "+selected,()->{
            IOException original=new IOException("synthetic transport failure "+MEDIA);
            DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->{String a=action(h);if(a.equals(selected))throw original;return response(200,soap(a,a.equals("GetTransportInfo")?"<CurrentTransportState>PLAYING</CurrentTransportState>":""));});
            IOException failure=rejected(()->{switch(selected){case "SetAVTransportURI":c.setMedia(MEDIA,"fixture title");break;case "Play":c.play();break;case "Pause":c.pause();break;case "Stop":c.stop();break;case "Seek":c.seek(1000);break;default:c.status();}});
            typed(failure,selected,0,"");check(failure.getCause()==original,"original transport cause identity");String text=diagnostics(c);check(text.contains(selected)&&text.contains("请求失败"),"last failure action/reason");privateBounded(text);
        });
        group("SocketTimeout is timed out, never reported as cancellation",()->{SocketTimeoutException timeout=new SocketTimeoutException("synthetic timeout "+MEDIA);DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->{throw timeout;});IOException failure=rejected(c::play);typed(failure,"Play",0,"");check(failure.getCause()==timeout,"timeout original cause");String text=diagnostics(c);check(text.contains("超时")&&!text.contains("取消")&&!failure.getMessage().contains("取消"),"timeout classification remains distinct from cancellation");privateBounded(text);});
        group("HTTP403 carries the action and preserves parser cause",()->{DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->response(403,"not XML "+SECRET));IOException failure=rejected(c::play);typed(failure,"Play",403,"");check(failure.getCause().getCause()!=null,"HTTP wrapper retains XML parser cause chain");check(diagnostics(c).contains("HTTP=403")&&diagnostics(c).contains("Play=失败"),"HTTP action and failed receipt recorded");privateBounded(diagnostics(c));});
        for(int status:Arrays.asList(200,500))group("SOAP Fault preserves reported UPnP code HTTP"+status,()->{DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->response(status,fault("701","Transition not available")));IOException failure=rejected(c::play);typed(failure,"Play",status,"701");check(failure.getMessage().contains("701"),"readable SOAP failure code");String text=diagnostics(c);check(text.contains("HTTP="+status)&&text.contains("UPnP=701"),"structured SOAP codes in diagnostics");privateBounded(text);});
        group("GetPositionInfo401 still fails without GetMediaInfo fallback",()->{List<String> calls=new ArrayList<>();DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->{String a=action(h);calls.add(a);return a.equals("GetTransportInfo")?response(200,soap(a,"<CurrentTransportState>PLAYING</CurrentTransportState>")):response(500,fault("401","Invalid Action"));});IOException failure=rejected(c::status);typed(failure,"GetPositionInfo",500,"401");check(calls.equals(Arrays.asList("GetTransportInfo","GetPositionInfo")),"no fallback, partial-state downgrade or new action");check(diagnostics(c).contains("GetPositionInfo"),"last failed polling action is visible");});
        group("remote fault text is not a diagnostics or exception payload",()->{DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->response(500,fault("501","&lt;s:Envelope&gt;"+SECRET+" "+MEDIA)));IOException failure=rejected(c::play);typed(failure,"Play",500,"501");privateBounded(diagnostics(c));check(!failure.getMessage().contains(SECRET)&&!failure.getMessage().contains(MEDIA),"public failure summary never reflects remote text");});
        group("malformed XML is labelled with its polling action",()->{DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->{String a=action(h);return a.equals("GetTransportInfo")?response(200,soap(a,"<CurrentTransportState>PLAYING</CurrentTransportState>")):response(200,"<broken>");});IOException failure=rejected(c::status);typed(failure,"GetPositionInfo",200,"");check(diagnostics(c).contains("GetPositionInfo"),"XML poll failure action recorded");});
        for(String invalid:Arrays.asList(soap("Pause",""),soap("Play","").replace(SERVICE,"urn:other"),"<root/>",soap("Play","").replace("</s:Body>","<x:Extra xmlns:x='x'/></s:Body>")))group("invalid SOAP success remains failure",()->{DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->response(200,invalid));typed(rejected(c::play),"Play",200,"");});
        group("invalid status fields retain exact failing action",()->{for(boolean transport:new boolean[]{true,false}){DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->{String a=action(h);return response(200,soap(a,a.equals("GetTransportInfo")?(transport?"<CurrentTransportState>PLAYING</CurrentTransportState><CurrentTransportState>STOPPED</CurrentTransportState>":"<CurrentTransportState>PLAYING</CurrentTransportState>"):"<TrackURI>"+MEDIA+"</TrackURI><RelTime>00:99:00</RelTime>"));});typed(rejected(c::status),transport?"GetTransportInfo":"GetPositionInfo",200,"");}});
        group("last failure survives a later successful poll",()->{boolean[] fail={true};DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->{String a=action(h);if(fail[0])throw new SocketTimeoutException("synthetic timeout");return response(200,soap(a,a.equals("GetTransportInfo")?"<CurrentTransportState>PLAYING</CurrentTransportState>":"<RelTime>NOT_IMPLEMENTED</RelTime><TrackDuration>NOT_IMPLEMENTED</TrackDuration>"));});rejected(c::pause);fail[0]=false;check(c.status().state.equals("PLAYING"),"subsequent successful status unchanged");check(diagnostics(c).contains("Pause")&&diagnostics(c).contains("超时"),"last failure retained as history, not silently cleared by subsequent action");});
        group("concurrent diagnostic read is bounded and does not wait for network",()->{CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);DlnaControl c=new DlnaControl(device(),(u,m,h,b,t)->{entered.countDown();try{if(!release.await(2,TimeUnit.SECONDS))throw new IOException("fixture timeout");}catch(InterruptedException failure){Thread.currentThread().interrupt();throw new IOException(failure);}return response(200,soap(action(h),""));});Throwable[] failure={null};Thread worker=new Thread(()->{try{c.play();}catch(Throwable error){failure[0]=error;}});worker.start();try{check(entered.await(1,TimeUnit.SECONDS),"request entered transport");for(int i=0;i<32;i++){String text=diagnostics(c);check(text.contains("Play=请求中"),"coherent in-flight receipt");privateBounded(text);}}finally{release.countDown();worker.join(2500);}check(!worker.isAlive()&&failure[0]==null,"diagnostics does not interfere with actual action");check(diagnostics(c).contains("Play=已受理"),"receipt committed after transport completes");});
        System.out.println("DLNA_CONTROL_DIAGNOSTICS "+(failed==0?"OK":"FAILED")+" groupsPassed="+passed+" groupsFailed="+failed+" checks="+checks+" networkRequests=0 deviceTests=not_run");if(failed>0)System.exit(1);
    }
}
